const body = $json.body || $json;
const text = body.text || body.message || body.input || body.prompt || '';
if (!text) {
  return [{ json: { error: true, message: 'Missing text/message/input/prompt field.', received: body } }];
}
return [{ json: { text, received: body } }];

const report = $json.report || {};
const raw = $json.raw_result || {};
const decision = report.decision || raw.policy || 'UNKNOWN';
let route = 'REVIEW';
let shouldContinue = false;
let message = 'ACA Runtime routed this input for review.';
if (decision === 'ALLOW') {
  route = 'ALLOW';
  shouldContinue = true;
  message = 'Input allowed by ACA Runtime.';
} else if (decision === 'CLARIFY') {
  route = 'CLARIFY';
  message = 'Input requires clarification before continuing.';
} else if (decision === 'FLAG_DRIFT' || decision === 'AMBIGUOUS_DRIFT') {
  route = 'REVIEW';
  message = 'Input may indicate drift or boundary pressure; review before continuing.';
}
return [{ json: { route, should_continue: shouldContinue, message, decision, runtime_status: report.runtime_status || null, semantic_field: report.semantic_field || raw.best_field || null, origin_cost: report.origin_cost ?? raw.origin_cost ?? null, ambiguity: report.ambiguity || raw.ambiguity_status || null, criterion_confidence: report.criterion_confidence ?? null, trajectory_state: report.trajectory_state || null, aca_response: $json } }];
